    act: { title: 'The 3-Step Friendship Handshake Practice', obj: 'Practice introducing yourself using 3-step method.', mats: ['Partner or mirror'], steps: ['Stand 3 feet apart with smile.', 'Step 1: Greet and state name clearly.', 'Step 2: Ask friendly question.', 'Step 3: Listen and offer shared activity.'], output: 'Demonstrated introduction signed off by caregiver or teacher.', precautions: 'Always practice introductions in safe supervised environments.', alt: 'Write a warm welcome card for a new classmate or neighbor.' },
